algorithms.pseudocode:
INPUT : file x[0..n-1] of integer triples (a,b,c)
OUTPUT: (branch, seed) if the file is seed-compressible, else NONE

if n < 2: return NONE

# stage 1 -- conserved quantities, O(n) subtractions
admissible <- {}
if { c - b : (a,b,c) in x } is a singleton: admissible <- admissible + {A}
if { |b - a| : (a,b,c) in x } is a singleton: admissible <- admissible + {B}
if { c - a : (a,b,c) in x } is a singleton: admissible <- admissible + {C}
if admissible is empty: return NONE                 # fast rejection

# stage 2 -- transition classifier, O(1) per transition
labels <- {}
for t = 0 .. n-2:
    found <- NONE
    for s in {A, B, C}: if s(x[t]) = x[t+1] then found <- s
    labels <- labels + {found}
if |labels| != 1 or NONE in labels: return NONE     # no single branch explains the file
branch <- the unique element of labels

# stage 3 -- verification by exact replay (the falsifiability gate)
p <- x[0]
for t = 0 .. n-1:
    if p != x[t]: return NONE
    p <- branch(p)
return (branch, x[0])
